import request from '@/utils/request'
function handleData(val) {
  return val.slice(0, 4) + '****' + val.slice(val.length - 8, val.length)
}
export function getIssueDetail(data) {
  return request({
    url: '/issuekey/issueDetail',
    method: 'get',
    params: data
  }).then(res => {
    res.blockkeyShow = handleData(res.blockkey)
    res.blockurlShow = handleData(res.blockurl)
    return res
  })
}
